#!/usr/bin/env python3
from pathlib import Path
import json,sys
root=Path(sys.argv[1]);out=Path(sys.argv[2]);checks=[]
def ck(i,ok,d=''):checks.append({'id':i,'passed':bool(ok),'detail':str(d)})
def txt(p):return (root/p).read_text()
paths=['src/games/mk2/research/fn4Slot16PaletteContextRgbaFixtures.ts','src/components/MK2FoundationPanel.tsx','src/appMetadata.ts','metadata.json','package.json','scripts/run-mk2-fn4-slot16-palette-context-rgba.mjs','scripts/audit-mk2-o85.py']
for p in paths:ck('exists_'+p,(root/p).is_file(),p)
s=txt(paths[0]);panel=txt(paths[1]);meta=txt(paths[2]);md=json.loads(txt(paths[3]));pkg=json.loads(txt(paths[4]));runner=txt(paths[5]);audit=txt(paths[6])
ck('verdict','MK2_FN4_SLOT16_CONNECTED_PROVENANCE_ALIASED_PALETTE_CONTEXT_RGBA_FIXTURES_ESTABLISHED' in s)
ck('identity',"RESOURCE='FN4.GRA'" in s and 'RESOURCE_ID=119' in s and 'SLOT=16' in s)
ck('fn4_hash','baba701ccf9301913a575daec0810827601553fc3bc846a4877907083acb6185' in s)
ck('root','rootObject2:0x208c' in s and 'rootFieldSource:0x208c' in s and 'level1Target:0x21e0' in s)
ck('descriptor','level1FieldSource:0x21ea' in s and 'level2Target:0x220a' in s and 'descriptorObject2:0x27640' in s and 'descriptorPhysical:0xc8294' in s)
ck('fixups','edge(0x208c,0x21e0)' in s and 'edge(0x21ea,0x220a)' in s and 'edge(0x220a,0x27640)' in s)
ck('palette_A','0x2ad2a' in s.lower() and '0x8c97e' in s.lower() and 'dcb616533af566e337a1c0669f5d4e41121b73630581f26954aacf059d3a7253' in s)
ck('palette_B_alias',s.count('dcb616533af566e337a1c0669f5d4e41121b73630581f26954aacf059d3a7253')>=2 and 'A/B palettes must alias the same record' in s)
ck('semantics','DEFAULT_CHARACTER_PALETTE' in s and 'SAME_CHARACTER_DUPLICATE_OVERRIDE_PALETTE' in s)
ck('alias_decision','slot16PaletteSelectorsAliasSameRecord:true' in s and 'sameCharacterDuplicateVisualOverrideNoOpForSlot16:true' in s)
ck('pair_check','slot16_context_pairs_identical' in s and '27/27 A/B RGBA pairs byte-identical' in s)
ck('stream_count','streamCount:27' in s and 'pngEntryCount:54' in s)
ck('scope',"scope:'FN4_SLOT16_ONLY_NOT_WHOLE_FN_FAMILY'" in s and 'wholeFNFamilyPaletteOwnershipPromoted:false' in s and 'humanFighterNamePromoted:false' in s)
ck('o73_correction','o73LooseFn6WitnessSupersededForSlot16Fixture:true' in s)
ck('package_name','MK2_O85_FN4_SLOT16_PALETTE_CONTEXT_RGBA_PACKAGE.zip' in s)
ck('panel_range','O67–O85' in panel)
ck('panel_import','executeMK2FN4Slot16PaletteContextRgbaFixtures' in panel and 'MK2FN4Slot16PaletteContextRgbaFixturesResult' in panel)
ck('panel_state','[o85,setO85]' in panel)
ck('panel_run','const t85=await executeMK2FN4Slot16PaletteContextRgbaFixtures' in panel and 'setO85(t85)' in panel)
ck('panel_card','O85 FN4 slot-16 connected-provenance RGBA verified' in panel)
ck('panel_alias','all 27 default/duplicate PNG pairs are byte-identical' in panel)
ck('panel_boundary','Scope is identity slot 16 + FN4.GRA only' in panel)
ck('panel_json','O85 FN4 Slot16 RGBA JSON' in panel)
ck('panel_download','Download FN4 Slot16 RGBA Package' in panel)
ck('panel_alert','same-character duplicate override a visual no-op for slot 16' in panel)
ck('milestone','1E.3O.85' in meta)
ck('metadata','1E.3O.85' in md.get('description',''))
ck('package_script',pkg['scripts'].get('smoke:mk2-fn4-slot16-palette-context-rgba')=='node scripts/run-mk2-fn4-slot16-palette-context-rgba.mjs')
ck('o84_retained','smoke:mk2-verified-fighter-rgba-bundle-o84' in pkg['scripts'])
ck('runner_chain',all(x in runner for x in ['executeMK2BroadIndexedGraphicsCorpusCensus','executeMK2CharacterResourcePaletteSlotJoin','executeMK2PaletteSelectorGameplaySemantics','executeMK2FN4Slot16PaletteContextRgbaFixtures']))
ck('audit_root','fn4_slot16_connected_root_edge' in audit)
ck('audit_rgba','all54RgbaPayloadsIndependentlyReconstructed' in audit)
ck('audit_pair_alias','all_27_context_pairs_identical' in audit and 'all27SelectorContextPairsByteIdentical' in audit)
ck('audit_scope','wholeFNFamilyPaletteOwnershipNotPromoted' in audit and 'humanFighterNameNotPromoted' in audit)
failed=[c for c in checks if not c['passed']]
res={'format':'mk2_o85_source_integration_audit_v1','checkCount':len(checks),'passedCount':len(checks)-len(failed),'failedCount':len(failed),'allChecksPassed':not failed,'checks':checks,'decision':{'o85SourceIntegrated':not failed,'slot16FN4ConnectedFixtureExposed':not failed,'slot16PaletteAliasNoOpExplicit':not failed,'wholeFNFamilyPaletteOwnershipNotPromoted':True,'humanFighterNameNotPromoted':True,'o81Slot4AndO83Slot5AuthoritiesPreserved':True,'verdict':'MK2_O85_SOURCE_UI_INTEGRATION_AUDIT_PASSED' if not failed else 'AUDIT_FAILED'}}
out.parent.mkdir(parents=True,exist_ok=True);out.write_text(json.dumps(res,indent=2));print(json.dumps({k:res[k] for k in ['checkCount','passedCount','failedCount','allChecksPassed']},indent=2))
if failed: print(json.dumps(failed,indent=2));sys.exit(1)
